import hmac
import hashlib
import base64
import json
import time
import os
from typing import Optional, Dict, Any
from dataclasses import dataclass
from enum import Enum


class Algorithm(Enum):
    RS256 = "RS256"
    HS256 = "HS256"


@dataclass
class KeyConfig:
    """Stores cryptographic key configuration."""
    rsa_public_key: bytes
    rsa_private_key: bytes
    hmac_secret: bytes
    allowed_algorithms: list


def _base64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('utf-8')


def _base64url_decode(s: str) -> bytes:
    padding = 4 - len(s) % 4
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s.encode('utf-8'))


class RSAVerifier:
    """Handles RSA signature verification using cryptography library."""

    def __init__(self, public_key_pem: bytes):
        self._public_key_pem = public_key_pem

    def verify(self, message: bytes, signature: bytes) -> bool:
        """Verify RSA-SHA256 signature."""
        try:
            from cryptography.hazmat.primitives import hashes, serialization
            from cryptography.hazmat.primitives.asymmetric import padding

            public_key = serialization.load_pem_public_key(self._public_key_pem)
            public_key.verify(
                signature,
                message,
                padding.PKCS1v15(),
                hashes.SHA256()
            )
            return True
        except Exception:
            return False


class HMACVerifier:
    """Handles HMAC-SHA256 signature verification."""

    def __init__(self, secret: bytes):
        self._secret = secret

    def verify(self, message: bytes, signature: bytes) -> bool:
        """Verify HMAC-SHA256 signature using constant-time comparison."""
        expected = hmac.new(self._secret, message, hashlib.sha256).digest()
        return hmac.compare_digest(expected, signature)


class TokenVerificationService:
    """Service for verifying authentication tokens.

    Supports RS256 (asymmetric) and HS256 (symmetric) algorithms.
    Algorithm selection is restricted to configured allowed list.
    """

    def __init__(self, config: KeyConfig):
        self._config = config
        self._verifiers = self._build_verifier_map(config)

    def _build_verifier_map(self, config: KeyConfig) -> Dict[str, Any]:
        """Build mapping of algorithm names to their verifier instances.

        Only algorithms in the allowed list get verifiers instantiated.
        """
        verifier_map = {}

        # Only create verifiers for allowed algorithms
        for alg in config.allowed_algorithms:
            if alg == Algorithm.RS256.value:
                verifier_map[Algorithm.RS256.value] = RSAVerifier(config.rsa_public_key)
            elif alg == Algorithm.HS256.value:
                verifier_map[Algorithm.HS256.value] = HMACVerifier(config.hmac_secret)

        return verifier_map

    def _get_verification_key(self, algorithm: str) -> Optional[Any]:
        """Get the appropriate verifier for the given algorithm.

        Returns None if algorithm is not in the allowed set.
        """
        return self._verifiers.get(algorithm)

    def _parse_token(self, token: str) -> Optional[Dict]:
        """Parse a JWT-format token into its components."""
        parts = token.split('.')
        if len(parts) != 3:
            return None

        try:
            header = json.loads(_base64url_decode(parts[0]))
            payload = json.loads(_base64url_decode(parts[1]))
            signature = _base64url_decode(parts[2])

            return {
                'header': header,
                'payload': payload,
                'signature': signature,
                'signed_content': f"{parts[0]}.{parts[1]}".encode('utf-8')
            }
        except (json.JSONDecodeError, Exception):
            return None

    def _validate_claims(self, payload: Dict) -> bool:
        """Validate standard JWT claims."""
        now = int(time.time())

        # Check expiration
        if 'exp' in payload:
            if now >= payload['exp']:
                return False

        # Check not-before
        if 'nbf' in payload:
            if now < payload['nbf']:
                return False

        # Check issuer
        if 'iss' in payload:
            allowed_issuers = ['auth.internal.service', 'auth.partner.service']
            if payload['iss'] not in allowed_issuers:
                return False

        return True

    def verify_token(self, token: str) -> Optional[Dict]:
        """Verify a JWT token and return its payload if valid.

        Performs:
        1. Token parsing and structure validation
        2. Algorithm whitelist check
        3. Signature verification using appropriate key
        4. Claims validation (exp, nbf, iss)

        Returns payload dict if valid, None otherwise.
        """
        parsed = self._parse_token(token)
        if parsed is None:
            return None

        header = parsed['header']

        # Validate header has required fields
        if 'alg' not in header or 'typ' not in header:
            return None

        if header['typ'] != 'JWT':
            return None

        algorithm = header['alg']

        # Check algorithm is in allowed set
        if algorithm not in [a.value for a in Algorithm]:
            return None

        # Get verifier for this algorithm
        verifier = self._get_verification_key(algorithm)
        if verifier is None:
            return None

        # Verify signature
        if not verifier.verify(parsed['signed_content'], parsed['signature']):
            return None

        # Validate claims
        if not self._validate_claims(parsed['payload']):
            return None

        return parsed['payload']


def create_default_config() -> KeyConfig:
    """Create default key configuration from environment."""
    rsa_pub = os.environ.get('RSA_PUBLIC_KEY', '').encode('utf-8')
    rsa_priv = os.environ.get('RSA_PRIVATE_KEY', '').encode('utf-8')
    hmac_secret = os.environ.get('HMAC_SECRET', '').encode('utf-8')

    return KeyConfig(
        rsa_public_key=rsa_pub,
        rsa_private_key=rsa_priv,
        hmac_secret=hmac_secret,
        allowed_algorithms=[Algorithm.RS256.value]
    )


# Application entry point for token verification
class AuthMiddleware:
    """Authentication middleware for request processing."""

    def __init__(self):
        self._config = create_default_config()
        # In production, only RS256 is allowed for external tokens
        # HS256 is reserved for internal service-to-service communication
        self._external_verifier = TokenVerificationService(self._config)

        # Internal service config allows both algorithms
        internal_config = KeyConfig(
            rsa_public_key=self._config.rsa_public_key,
            rsa_private_key=self._config.rsa_private_key,
            hmac_secret=self._config.rsa_public_key,  # Shared key derived from RSA pub
            allowed_algorithms=[Algorithm.RS256.value, Algorithm.HS256.value]
        )
        self._internal_verifier = TokenVerificationService(internal_config)

    def authenticate_request(self, headers: Dict[str, str], is_internal: bool = False) -> Optional[Dict]:
        """Authenticate a request using its Authorization header."""
        auth_header = headers.get('Authorization', '')

        if not auth_header.startswith('Bearer '):
            return None

        token = auth_header[7:]

        # Route to appropriate verifier based on request source
        if is_internal:
            return self._internal_verifier.verify_token(token)
        else:
            return self._external_verifier.verify_token(token)

    def authenticate_websocket(self, token: str, origin: str) -> Optional[Dict]:
        """Authenticate WebSocket connections.

        WebSocket connections from internal origins use internal verification.
        """
        internal_origins = ['wss://internal.service.local', 'wss://monitoring.internal']
        is_internal = origin in internal_origins

        headers = {'Authorization': f'Bearer {token}'}
        return self.authenticate_request(headers, is_internal=is_internal)
